    38→/**
    39→ * Minimal empty state for habits screen
    40→ *
    41→ * Provides a streamlined flow for creating the first habit:
    42→ * 1. Hero icon with breathing animation
    43→ * 2. Question headline
    44→ * 3. Text input or suggestion chips
    45→ * 4. Primary CTA button
    46→ * 5. Success celebration on creation
    47→ */
    48→export function HabitsEmptyStateMinimal({
    49→  isLoading = false,
