    61→  // Extract bottom inset for use in worklet (capture at mount)
    62→  const bottomInset = insets.bottom;
    63→
    64→  // Timing config for keyboard-aware transitions
    65→  const timingConfig = {
    66→    duration: shouldReduceMotion ? 0 : KEYBOARD_LAYOUT.transitionDuration,
