    68→  };
    69→
    70→  // Animated styles for keyboard-aware compact mode
    71→  const containerAnimatedStyle = useAnimatedStyle(() => ({
    72→    justifyContent: isKeyboardVisible ? 'flex-start' : 'center',
    73→    paddingBottom: withTiming(
    74→      isKeyboardVisible ? 0 : bottomInset + 20, // +20 for breathing room above safe area
    75→      timingConfig
    76→    ),
    77→    paddingTop: withTiming(
    78→      isKeyboardVisible ? KEYBOARD_LAYOUT.topPadding : 0,
    79→      timingConfig
