    86→        scale: withTiming(
    87→          isKeyboardVisible ? KEYBOARD_LAYOUT.compactHeroSize / 80 : 1,
    88→          timingConfig
    89→        ),
    90→      },
    91→    ],
    92→  }));
    93→
    94→  const headlineAnimatedStyle = useAnimatedStyle(() => ({
    95→    fontSize: withTiming(
