   111→    maxHeight: withTiming(isKeyboardVisible ? 0 : 100, timingConfig),
   112→    opacity: withTiming(isKeyboardVisible ? 0 : 1, timingConfig),
   113→    overflow: 'hidden' as const,
   114→  }));
