    37→const AnimatedPressable = Animated.createAnimatedComponent(Pressable);
    38→
    39→interface ChipProps {
    40→  chip: SuggestionChip;
    41→  index: number;
    42→  isSelected: boolean;
    43→  onPress: () => void;
    44→  /** Stagger delay for entrance animation (ms) */
    45→  staggerDelay: number;
    46→}
