    57→function Chip({ chip, isSelected, onPress, staggerDelay }: ChipProps) {
    58→  const { triggerSelection } = useHapticFeedback();
    59→  const shouldReduceMotion = useReducedMotion();
    60→  const scale = useSharedValue(1);
    61→  const translateY = useSharedValue(0);
    62→  const shadowOpacity = useSharedValue(0);
    63→  const selectionProgress = useSharedValue(isSelected ? 1 : 0);
    64→
    65→  // Entrance animation values
    66→  const entranceOpacity = useSharedValue(shouldReduceMotion ? 1 : 0);
    67→  const entranceTranslateY = useSharedValue(
    68→    shouldReduceMotion ? 0 : CHIP_STAGGER.translateY
    69→  );
    70→
    71→  // Calculate total entrance delay: base chips delay + individual stagger
    72→  const totalEntranceDelay = ENTRANCE_DELAYS.chips + staggerDelay;
    73→
    74→  // Trigger entrance animation on mount
    75→  useEffect(() => {
    76→    if (shouldReduceMotion) {
    77→      entranceOpacity.value = 1;
    78→      entranceTranslateY.value = 0;
    79→      return;
    80→    }
    81→
    82→    // Fade in with ease-out timing
    83→    entranceOpacity.value = withDelay(
    84→      totalEntranceDelay,
    85→      withTiming(1, {
    86→        duration: CHIP_STAGGER.duration,
    87→        easing: Easing.out(Easing.ease),
    88→      })
    89→    );
    90→
    91→    // Slide up with ease-out timing
    92→    entranceTranslateY.value = withDelay(
    93→      totalEntranceDelay,
    94→      withTiming(0, {
    95→        duration: CHIP_STAGGER.duration,
    96→        easing: Easing.out(Easing.ease),
    97→      })
    98→    );
    99→  }, [
   100→    entranceOpacity,
   101→    entranceTranslateY,
   102→    shouldReduceMotion,
   103→    totalEntranceDelay,
   104→  ]);
   105→
   106→  // Update selection progress when prop changes
   107→  if (
   108→    (isSelected && selectionProgress.value === 0) ||
   109→    (!isSelected && selectionProgress.value === 1)
   110→  ) {
   111→    selectionProgress.value = shouldReduceMotion
   112→      ? isSelected
   113→        ? 1
   114→        : 0
   115→      : withSpring(isSelected ? 1 : 0, SPRING_CONFIGS.chipPress);
   116→  }
   117→
   118→  const animatedStyle = useAnimatedStyle(() => ({
   119→    // Using emerald-700 (#047857) for WCAG AA contrast (5.21:1 with white text)
   120→    backgroundColor: interpolateColor(
   121→      selectionProgress.value,
   122→      [0, 1],
   123→      ['#ffffff', '#047857']
   124→    ),
   125→
   126→    borderColor: interpolateColor(
   127→      selectionProgress.value,
   128→      [0, 1],
   129→      [COLORS.stone200, '#047857']
   130→    ),
   131→
   132→    // Entrance opacity
   133→    opacity: entranceOpacity.value,
   134→
   135→    // Shadow increases on hover
   136→    shadowOpacity: shadowOpacity.value,
   137→
   138→    // Combine entrance translateY with interaction translateY
   139→    transform: [
   140→      { translateY: entranceTranslateY.value + translateY.value },
   141→      { scale: scale.value },
   142→    ],
   143→  }));
   144→
   145→  const textStyle = useAnimatedStyle(() => ({
   146→    color: interpolateColor(
   147→      selectionProgress.value,
   148→      [0, 1],
   149→      [COLORS.stone700, '#ffffff']
   150→    ),
   151→  }));
   152→
   153→  // Hover state: lift up, scale up, increase shadow
   154→  const handlePressIn = useCallback(() => {
   155→    if (shouldReduceMotion) return;
   156→    translateY.value = withSpring(
   157→      CHIP_TRANSFORMS.hoverTranslateY,
   158→      SPRING_CONFIGS.chipHover
   159→    );
   160→    scale.value = withSpring(
   161→      CHIP_TRANSFORMS.hoverScale,
   162→      SPRING_CONFIGS.chipHover
   163→    );
   164→    shadowOpacity.value = withSpring(0.15, SPRING_CONFIGS.chipHover);
   165→  }, [scale, shadowOpacity, shouldReduceMotion, translateY]);
   166→
   167→  // Release: animate back to rest state
   168→  const handlePressOut = useCallback(() => {
   169→    if (shouldReduceMotion) return;
   170→    scale.value = withSpring(
   171→      CHIP_TRANSFORMS.selectedScale,
   172→      SPRING_CONFIGS.chipPress
   173→    );
   174→    translateY.value = withSpring(0, SPRING_CONFIGS.chipHover);
   175→    shadowOpacity.value = withSpring(0, SPRING_CONFIGS.chipHover);
   176→  }, [scale, shadowOpacity, shouldReduceMotion, translateY]);
   177→
   178→  // Selection: haptic feedback + callback
   179→  const handlePress = useCallback(() => {
   180→    triggerSelection();
   181→    // Brief press feedback (scale down then back up)
   182→    if (!shouldReduceMotion) {
   183→      scale.value = withSpring(
   184→        CHIP_TRANSFORMS.pressScale,
   185→        SPRING_CONFIGS.chipPress
   186→      );
   187→    }
   188→    onPress();
   189→  }, [onPress, scale, shouldReduceMotion, triggerSelection]);
   190→
   191→  return (
   192→    <AnimatedPressable
   193→      accessibilityLabel={`Select ${chip.fullName}`}
   194→      accessibilityRole='button'
   195→      accessibilityState={{ selected: isSelected }}
   196→      style={[
   197→        animatedStyle,
   198→        {
   199→          alignItems: 'center',
   200→          borderRadius: BORDER_RADIUS.chip,
   201→          borderWidth: 1,
   202→          elevation: 1,
   203→          flexDirection: 'row',
   204→          gap: 6,
   205→          minHeight: TOUCH_TARGETS.chipHeight,
   206→          paddingHorizontal: 16,
   207→
   208→          paddingVertical: 10,
   209→          // Base shadow properties - subtle (opacity animates on hover)
   210→          shadowColor: '#000000',
   211→          shadowOffset: { height: 1, width: 0 },
   212→          shadowRadius: 2,
   213→        },
   214→      ]}
   215→      onPress={handlePress}
   216→      onPressIn={handlePressIn}
   217→      onPressOut={handlePressOut}
   218→    >
   219→      <Text style={{ fontSize: 18 }}>{chip.emoji}</Text>
   220→      <Animated.Text
   221→        style={[
   222→          textStyle,
   223→          {
   224→            fontSize: 15,
   225→            fontWeight: '600',
   226→          },
   227→        ]}
   228→      >
   229→        {chip.label}
   230→      </Animated.Text>
   231→    </AnimatedPressable>
   232→  );
   233→}
